entries[257444] = { ["name"] = "Hexed Vilefeather Eagle", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"Once a proud sky-hunter, she now soars on withered wings, her spirit twisted by lingering necromantic curses that seep through every rotting plume and ghostlit eye.\"\nTreasure:\nAbandoned Ritual Skull\nZone:\nZul'Aman" }
entries[257445] = { ["name"] = "Ravenous Shredclaw", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nRequires Renown Rank 17 with The Singularity.\n\n\"Fast and dependable, Shredclaws were one of the first creatures tamed in the Voidstorm. Their owners learned quickly not to leave them alone with their pets.\"\nVendor:\nVoid Researcher Anomander\nZone:\nVoidstorm\nCost:\n6000" }
entries[257446] = { ["name"] = "Reins of the Insatiable Shredclaw", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"The shredclaw has fully embraced the way of the Void: never satisfied, constantly seeking out new strength to dominate and new prey to devour.\"\nTreasure:\nFinal Clutch of Predaxas\nZone:\nVoidstorm" }
entries[257447] = { ["name"] = "Prowling Shredclaw", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nRequires Slayer's Duellum\n- Exalted\n\n\"According to ren'dorei scouts, shredclaws are often seen hunting in packs.\"\nVendor:\nThraxadar\nZone:\nMasters' Perch\nFaction:\nSlayer's Duellum - Exalted\nCost:\n6000" }
entries[257448] = { ["name"] = "Frenzied Shredclaw", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nRequires Slayer's Duellum\n- Exalted\n\n\"Once a pack member dies, these shredclaws enter a frenzy of rage that not even a hulking ultradon can stop.\"\nVendor:\nThraxadar\nZone:\nMasters' Perch\nFaction:\nSlayer's Duellum - Exalted\nCost:\n6000" }
entries[257502] = { ["name"] = "Vicious Snaplizard", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"These creatures are found sneaking through the battlefield and climbing over obstactles, ready to cause trouble for the Alliance.\"\nPvP:\nMidnight: Season 1\nRated Arena and Rated Battleground Season Reward" }
