entries[258475] = { ["name"] = "Tuskarr Shoreglider", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"The Tuskarr learned long ago that some of the bones of the sea creatures they hunted were light and buoyant, making for effective glider materials.\"\nPromotion" }
entries[258476] = { ["name"] = "Frostbrood Proto-Wyrm", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"The same magic of undeath that raised the Frostbrood into the Lich King's service has infused this primal wyrm. Its loyalty and ferocity now serve those who defend Azeroth.\"\nPromotion:\nWrath of the Lich King Classic" }
entries[258477] = { ["name"] = "Telix the Stormhorn", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"Once a simple beetle of the Forbidden Reach, Telix became infused with storm magic when Raszageth was unleashed. With its newly heightened senses, Telix roams the Dragon Isles alongside the Dragonscale Expedition--and you!\"\nPromotion" }
entries[258479] = { ["name"] = "Algarian Stormrider", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"Flying true even in the harshest conditions, this lightning-infused rook was trained to soar through the skies of the Isle of Dorn and into the depths below.\"\nPromotion:\nThe War Within Heroic Edition" }
