entries[259189] = { ["name"] = "Aged Cruor", ["text"] = "Binds when picked up\nUse: Study to increase your Midnight Alchemy Knowledge by 1.\nRequires Midnight Alchemy (1)" }
entries[259190] = { ["name"] = "Thalassian Whestone", ["text"] = "Binds when picked up\nUse: Study to increase your Midnight Blacksmithing Knowledge by 2.\nRequires Midnight Blacksmithing (1)\n\"While the craftsmanship is impressive, this aged whetstone is no longer practically useful. You can study it though to improve your Blacksmithing knowledge!\"" }
entries[259191] = { ["name"] = "Infused Quenching Oil", ["text"] = "Binds when picked up\nUse: Study to increase your Midnight Blacksmithing Knowledge by 2.\nRequires Midnight Blacksmithing (1)\n\"An advanced product utilizing the skills of Alchemists, Enchanters, and Blacksmiths, studying this oil can help deepen your understanding of practical application of Thalassian smithing techniques.\"" }
entries[259192] = { ["name"] = "Voidstorm Ashes", ["text"] = "Binds when picked up\nUse: Study to increase your Midnight Enchanting Knowledge by 2.\nRequires Midnight Enchanting (1)\n\"A fine dust from the Voidstorm, it contains latent magic for enchanters to study. Doing so will yield knowledge!\"" }
entries[259193] = { ["name"] = "Lost Thalassian Vellum", ["text"] = "Binds when picked up\nUse: Study to increase your Midnight Enchanting Knowledge by 2.\nRequires Midnight Enchanting (1)\n\"A previously-lost vellum containing Thalassian-based magics. While it doesn't have any practical use, you can study it for Enchanting Knowledge!\"" }
entries[259194] = { ["name"] = "Dance Gear", ["text"] = "Binds when picked up\nUse: Study to increase your Midnight Engineering Knowledge by 1.\nRequires Midnight Engineering (1)\n\"While they don't have any practical applications, studying them can help improve your knowledge of Thalassian engineering techniques. They also happen to pair well with Song Gears.\"" }
entries[259195] = { ["name"] = "Dawn Capacitor", ["text"] = "Binds when picked up\nUse: Study to increase your Midnight Engineering Knowledge by 1.\nRequires Midnight Engineering (1)\n\"A strange device that emits a bright, golden glow. While you don't have any practical uses for it, you could disassemble it and study it to improve your Engineering knowledge!\"" }
entries[259196] = { ["name"] = "Brilliant Phoenix Ink", ["text"] = "Binds when picked up\nUse: Study to increase your Midnight Inscription Knowledge by 2.\nRequires Midnight Inscription (1)\n\"The magic flowing through this ink has long expired, but its brilliant hue is still a sight to behold. Studying it can help you deepen your understanding of Thalassian scribe techniques.\"" }
entries[259197] = { ["name"] = "Loa-Blessed Rune", ["text"] = "Binds when picked up\nUse: Study to increase your Midnight Inscription Knowledge by 2.\nRequires Midnight Inscription (1)\n\"An ancient rune blessed with the power of the Loa. While you're unsure what it would do, or how to even utilize it, the masterful craftsmanship of the rune can help you with your studies as a scribe.\"" }
entries[259198] = { ["name"] = "Void-Touched Eversong Diamond Fragments", ["text"] = "Binds when picked up\nUse: Study to increase your Midnight Jewelcrafting Knowledge by 2.\nRequires Midnight Jewelcrafting (1)\n\"Unusable, but hints of voidlight shimmer within the depths of the gem. Studying it can yield new Jewelcrafting Knowledge.\"" }
entries[259199] = { ["name"] = "Harandar Stone Sample", ["text"] = "Binds when picked up\nUse: Study to increase your Midnight Jewelcrafting Knowledge by 2.\nRequires Midnight Jewelcrafting (1)\n\"A sample of stone from Harandar, steeped in the primal magic of Azeroth. Studying it will yield Jewelcrafting Knowledge.\"" }
entries[259200] = { ["name"] = "Amani Tanning Oil", ["text"] = "Binds when picked up\nUse: Study to increase your Midnight Leatherworking Knowledge by 2.\nRequires Midnight Leatherworking (1)\n\"Made from the trees of Zul'Aman, the Amani trolls use this for treating their leather. Studying it will yield new knowledge!\"" }
entries[259201] = { ["name"] = "Thalassian Mana Oil", ["text"] = "Binds when picked up\nUse: Study to increase your Midnight Leatherworking Knowledge by 2.\nRequires Midnight Leatherworking (1)\n\"Perfect for treating hides in the use of powerful armor. Also great for studying to improve your Leatherworking!\"" }
entries[259202] = { ["name"] = "Embroidered Memento", ["text"] = "Binds when picked up\nUse: Study to increase your Midnight Tailoring Knowledge by 2.\nRequires Midnight Tailoring (1)" }
entries[259203] = { ["name"] = "Finely Woven Lynx Collar", ["text"] = "Binds when picked up\nUse: Study to increase your Midnight Tailoring Knowledge by 2.\nRequires Midnight Tailoring (1)" }
entries[259204] = { ["name"] = "Raider Ash Remains", ["text"] = "Quest Item\nUnique (15)\n\"The result of many failures piling up...\"" }
